import { useId } from "react";
import { B } from "@/lib/brand";

/**
 * The Method Co. mark: an M made of a solid left half and a green right half
 * that meet in a V. Same geometry as the files in brand/ (generated by
 * script/brand/build-svgs.py), drawn inline so it costs no request.
 *
 * `tone` sets the solid half: "dark" backgrounds get white, "light" get navy.
 */
export default function BrandMark({
  size = 30,
  tone = "dark",
  title,
}: {
  /** Width in px. Height follows the 160:112 ratio. */
  size?: number;
  tone?: "dark" | "light";
  /** Accessible name. Leave out when the mark sits next to the written name. */
  title?: string;
}) {
  const gid = `mg-${useId().replace(/:/g, "")}`;
  return (
    <svg
      viewBox="0 0 160 112"
      width={size}
      height={(size * 112) / 160}
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
      style={{ display: "block", flexShrink: 0 }}
    >
      <defs>
        <linearGradient id={gid} gradientUnits="userSpaceOnUse" x1="80" y1="85.2" x2="160" y2="0">
          <stop offset="0" stopColor={B.greenDark} />
          <stop offset="0.55" stopColor={B.green} />
          <stop offset="1" stopColor={B.greenGlow} />
        </linearGradient>
      </defs>
      <path d="M0 0 L80 63.2 L80 85.2 L29 44.91 L29 112 L0 112 Z" fill={tone === "dark" ? B.white : B.bg} />
      <path d="M160 0 L80 63.2 L80 85.2 L131 44.91 L131 112 L160 112 Z" fill={`url(#${gid})`} />
    </svg>
  );
}
